                    /**
                     * Format: date-time
                     * @description When scores freeze, ISO 8601. Must be after startsAt; at most 3 years later.
                     */
                    endsAt: string;
                    /**
                     * @description The single platform players compete on. Cannot change after publishing.
                     * @enum {string}
                     */
                    platform: "messenger" | "instagram" | "whatsapp" | "zalo" | "telegram" | "tiktok" | "threads" | "email" | "gamification";
                    /**
                     * @description Host channel (inbox) whose events score; required for every platform except gamification. Must match the platform (email → SMTP inbox). Get ids from `inboxes.list`.
                     * @default null
                     */
                    inboxId?: string | null;
                    /**
                     * @description Gamification only: the minigame whose wins/shares score. Get ids from `minigames.list`.
                     * @default null
                     */
                    minigameId?: string | null;
