                        conversationId: string | null;
                        inboxId: string | null;
                        channel: string | null;
                        customerName: string | null;
                        customerEmail: string | null;
                        customerPhone: string | null;
                        shippingType: ("delivery" | "pickup") | null;
                        shippingAddress: {
                            line1?: string | null;
                            line2?: string | null;
                            city?: string | null;
                            state?: string | null;
                            zip?: string | null;
                            country?: string | null;
                        } | null;
                        note: string | null;
                        /** @description 1–5 when the customer rated the order. */
                        rating: number | null;
                        ratingComment: string | null;
                        cancelReason: string | null;
                        acceptedAt: string | null;
                        shippedAt: string | null;
