                            type: "immediately" | "seconds" | "minutes" | "hours" | "randomWithin3Minutes" | "randomWithin5Minutes" | "randomWithin10Minutes" | "randomWithin20Minutes" | "randomWithin30Minutes" | "randomWithin60Minutes";
