                                hasPhoneNumber: boolean;
                                /** @description Hide comments with an image attachment (Facebook only). */
                                hasImage: boolean;
                                /** @description Hide comments with a video attachment (Facebook only). */
                                hasVideo: boolean;
                                /** @description Hide comments containing a link. */
                                hasLink: boolean;
                                /** @description Hide comments containing any word in `keywords`. */
                                hasKeywords: boolean;
                                /** @description Hide comments containing a GIF. Only Facebook and Threads detect GIFs; ignored on other channels. Omitted means off. */
                                hasGif?: boolean;
                                /** @description Hide comments containing an emoji. Omitted means off. */
                                hasEmoji?: boolean;
