                        channel: "whatsapp" | "messenger" | "instagram" | "zalo" | "tiktok";
                        /** @description Inbox this channel feeds. See `inboxes.list`. */
                        inboxId: string;
                        /** @description Display name (page, account or number name). */
                        name: string;
                        /** @description Vendor account id: WhatsApp phone number id, Messenger page id, Instagram id, Zalo OA id or TikTok open id. */
                        externalId: string;
                        /** @description WhatsApp Business Account id. */
                        wabaId: string | null;
                        /** @description WhatsApp phone number. */
                        displayPhoneNumber: string | null;
                        /** @description Instagram username. */
                        username: string | null;
                        /** @description Whether coexistence sync is enabled. */
                        coexistEnabled: boolean;
                        /** @description WhatsApp only: number is also used in the WhatsApp Business app. */
                        isCoexist: boolean | null;
                        /** @description Legacy cached flag: whether the channel's own Meta token was granted the Conversions API permission. Prefer `capiConnected`. */
                        hasCapiScope: boolean;
                        /** @description Whether the Conversions API is set up for this channel: a dataset is set, it was not disconnected, and either a dedicated token was connected from the builder Ads tab or the channel (connected earlier) still sends with its own token. A channel that is not set up reads false even if the worker would create its dataset on the first event. */
                        capiConnected: boolean;
                        /** @description Meta dataset id for CAPI. */
                        datasetId: string | null;
                        /** @description Events Manager test code; while set, CAPI events go to Test Events, not production. */
                        capiTestEventCode: string | null;
                        /** @description Whether Conversions API was disconnected for this channel. */
                        capiDisconnected: boolean;
                        /** @description When tag sync was enabled; null when off or unsupported. */
                        syncTagEnabledAt: string | null;
                        /** @description WhatsApp/Messenger: flow that runs when a partner hands a conversation back. Change it with `updateHandoverResumeFlow` of the same channel group (e.g. `whatsappChannels.updateHandoverResumeFlow`). */
                        handoverResumeFlowId: string | null;
                        /** @description Set when the stored token needs the user to reconnect. */
                        tokenRefreshError: string | null;
                        /** @description Whether this channel can be used for click-to-message ads. Instagram accounts connected through native Instagram login are not eligible; only Facebook-login accounts are. */
                        adsEligible: boolean;
